#include "AssetDialogs.h"
#include <QComboBox>
#include <QDialogButtonBox>
#include "GlassDialogs.h"
#include <QFileInfo>
#include <QFormLayout>
#include <QLabel>
#include <QLineEdit>
#include <QListWidget>
#include <QMessageBox>
#include <QPushButton>
#include <QSpinBox>
#include <QTimer>
#include <QVBoxLayout>
#include <QUuid>

AssetPicker::AssetPicker(RpcClient *rpc,ThumbnailStore *thumbs,const QString &title,const QStringList &types,QWidget *parent):GlassDialog(parent){setWindowTitle(title);resize(820,620);auto l=new QVBoxLayout(this);auto search=new QLineEdit;search->setPlaceholderText(tr("搜索库内资产…"));l->addWidget(search);m_grid=new AssetGrid;m_model=new AssetModel(rpc,thumbs,this);m_grid->setModel(m_model);l->addWidget(m_grid,1);auto buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);l->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,this,[this]{if(!selectedAssets().isEmpty())accept();});connect(buttons,&QDialogButtonBox::rejected,this,&QDialog::reject);connect(m_grid,&QListView::activated,this,[this]{accept();});auto timer=new QTimer(this);timer->setSingleShot(true);timer->setInterval(220);connect(search,&QLineEdit::textChanged,timer,qOverload<>(&QTimer::start));auto filter=[this,search,types]{QJsonObject f{{"query",search->text()}};if(!types.isEmpty())f["types"]=QJsonArray::fromStringList(types);m_model->setFilter(f);};connect(timer,&QTimer::timeout,this,filter);filter();}
QJsonArray AssetPicker::selectedAssets()const{QJsonArray out;for(const auto &i:m_grid->selectionModel()->selectedIndexes())out.append(m_model->asset(i.row()));return out;}

OrderedEditor::OrderedEditor(RpcClient *rpc,ThumbnailStore *thumbs,const QJsonObject &asset,Mode mode,QWidget *parent):GlassDialog(parent),m_rpc(rpc),m_thumbs(thumbs),m_asset(asset),m_mode(mode){
    setWindowTitle(mode==Relations?tr("管理关联与材质贴图"):tr("管理预览图"));resize(760,570);m_cover=asset["cover_id"].toString("auto");auto layout=new QVBoxLayout(this);auto help=new QLabel(mode==Relations?tr("拖动排序。参考关联可关联任意资产；材质角色只对模型生效。同一槽位的同一角色保留一个绑定。"):tr("拖动排序。库内图片保留索引；外部图片只保存压缩预览，不会单独进入库。"));help->setWordWrap(true);layout->addWidget(help);
    auto body=new QHBoxLayout;m_list=new QListWidget;m_list->setDragDropMode(QAbstractItemView::InternalMove);m_list->setDefaultDropAction(Qt::MoveAction);m_list->setSelectionMode(QAbstractItemView::SingleSelection);m_list->setMinimumWidth(340);body->addWidget(m_list,1);auto form=new QFormLayout;m_label=new QLineEdit;form->addRow(tr("名称 / 标签"),m_label);m_role=new QComboBox;m_role->addItem(tr("普通参考"),"");for(const auto &[title,id]:QList<QPair<QString,QString>>{{tr("固有色"),"base_color"},{tr("法线"),"normal"},{tr("粗糙度"),"roughness"},{tr("金属度"),"metallic"},{tr("环境遮蔽 AO"),"ao"},{tr("自发光"),"emissive"},{tr("透明度"),"opacity"},{tr("ORM"),"orm"}})m_role->addItem(title,id);m_slot=new QSpinBox;m_slot->setRange(1,4096);m_slot->setValue(1);m_slot->setToolTip(tr("默认槽位 1、2、3；可直接输入更多槽位编号"));m_normal=new QComboBox;m_normal->addItem("OpenGL (+Y)","opengl");m_normal->addItem("DirectX (-Y)","directx");if(mode==Relations){auto preset=new QComboBox;preset->addItem(tr("选择固定 / 自定义标签…"));form->addRow(tr("快捷标签"),preset);m_rpc->call("role.list",{},this,[preset](const QJsonObject &r,const QString &error){if(!error.isEmpty())return;for(const auto &v:r["items"].toArray()){const auto role=v.toObject();const QString name=role["name"].toString();const int materialSlots=role["builtin"].toBool()?3:1;for(int slot=1;slot<=materialSlots;++slot){auto data=role;data["slot"]=slot;data["label"]=name+(slot>1?"_"+QString::number(slot):QString());preset->addItem(data["label"].toString(),data);}}});connect(preset,&QComboBox::activated,this,[this,preset](int index){if(index==0)return;const auto role=preset->currentData().toJsonObject();m_label->setText(role["label"].toString());m_role->setCurrentIndex(qMax(0,m_role->findData(role["render_role"].toString())));m_slot->setValue(role["slot"].toInt(1));editSelected();});form->addRow(tr("渲染角色"),m_role);form->addRow(tr("材质槽位"),m_slot);auto materialNames=new QLabel;materialNames->setWordWrap(true);QStringList materialRows;for(const auto &v:asset["metadata"].toObject()["materials"].toArray()){const auto material=v.toObject();materialRows<<tr("%1 · %2").arg(material["slot"].toInt()).arg(material["name"].toString());}materialNames->setText(materialRows.isEmpty()?tr("模型加载后显示实际材质名。槽位按模型材质顺序从 1 开始。"):materialRows.join("\n"));form->addRow(materialNames);form->addRow(tr("法线方向"),m_normal);auto note=new QLabel(tr("固有角色不可删除或重命名。普通参考可输入自定义标签。固有色使用 sRGB；ORM 通道为 R=AO、G=粗糙度、B=金属度。"));note->setWordWrap(true);form->addRow(note);}else{m_role->hide();m_slot->hide();m_normal->hide();auto cover=new QPushButton(tr("设为缩略图"));form->addRow(cover);connect(cover,&QPushButton::clicked,this,[this]{if(auto item=m_list->currentItem()){const auto o=item->data(Qt::UserRole).toJsonObject();m_cover=o["id"].toString(o["target_id"].toString());if(m_cover.isEmpty())m_cover=o["path"].toString();item->setToolTip(tr("已选为缩略图，保存后生效"));}});auto reset=new QPushButton(tr("恢复默认缩略图"));form->addRow(reset);connect(reset,&QPushButton::clicked,this,[this]{m_cover="auto";});}body->addLayout(form);layout->addLayout(body,1);
    auto actions=new QHBoxLayout;auto add=new QPushButton(tr("从库中添加"));actions->addWidget(add);connect(add,&QPushButton::clicked,this,&OrderedEditor::addLibrary);if(mode==Previews){auto external=new QPushButton(tr("添加外部图片"));actions->addWidget(external);connect(external,&QPushButton::clicked,this,[this]{const auto paths=GlassFiles::getOpenFileNames(this,tr("添加预览图"),{},tr("图片 (*.png *.jpg *.jpeg *.webp *.bmp *.tif *.tiff *.tga)"));for(const auto &path:paths)addItem({{"path",path},{"label",QFileInfo(path).fileName()}});});}auto remove=new QPushButton(tr("移除"));actions->addWidget(remove);connect(remove,&QPushButton::clicked,this,[this]{delete m_list->takeItem(m_list->currentRow());});auto up=new QPushButton(tr("上移"));auto down=new QPushButton(tr("下移"));actions->addWidget(up);actions->addWidget(down);connect(up,&QPushButton::clicked,this,[this]{move(-1);});connect(down,&QPushButton::clicked,this,[this]{move(1);});actions->addStretch();layout->addLayout(actions);
    auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);m_save=buttons->button(QDialogButtonBox::Save);m_save->setText(tr("保存更改"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,this,&OrderedEditor::save);connect(buttons,&QDialogButtonBox::rejected,this,&QDialog::reject);connect(m_list,&QListWidget::currentRowChanged,this,&OrderedEditor::selected);connect(m_label,&QLineEdit::textEdited,this,&OrderedEditor::editSelected);connect(m_role,&QComboBox::currentIndexChanged,this,&OrderedEditor::editSelected);connect(m_slot,&QSpinBox::valueChanged,this,&OrderedEditor::editSelected);connect(m_normal,&QComboBox::currentIndexChanged,this,&OrderedEditor::editSelected);
    for(const auto &v:asset[mode==Relations?"relations":"previews"].toArray())addItem(v.toObject());if(m_list->count())m_list->setCurrentRow(0);
}
void OrderedEditor::addItem(QJsonObject item){if(item["id"].toString().isEmpty())item["id"]=QUuid::createUuid().toString(QUuid::WithoutBraces);auto entry=new QListWidgetItem;entry->setData(Qt::UserRole,item);QString name=item["label"].toString();if(name.isEmpty())name=item["target"].toObject()["name"].toString();if(name.isEmpty())name=QFileInfo(item["path"].toString()).fileName();if(name.isEmpty())name=item["target_id"].toString();entry->setText(name);entry->setToolTip(item["path"].toString(item["target"].toObject()["source_path"].toString()));m_list->addItem(entry);m_list->setCurrentItem(entry);}
void OrderedEditor::selected(){m_changing=true;const auto item=m_list->currentItem();const auto o=item?item->data(Qt::UserRole).toJsonObject():QJsonObject();m_label->setText(o["label"].toString());m_role->setCurrentIndex(qMax(0,m_role->findData(o["role"].toString())));m_slot->setValue(o["slot"].toInt(1));m_normal->setCurrentIndex(qMax(0,m_normal->findData(o["normal_y"].toString("opengl"))));m_changing=false;}
void OrderedEditor::editSelected(){if(m_changing)return;if(auto item=m_list->currentItem()){auto o=item->data(Qt::UserRole).toJsonObject();o["label"]=m_label->text();if(m_mode==Relations){o["role"]=m_role->currentData().toString();o["slot"]=m_slot->value();o["normal_y"]=m_normal->currentData().toString();o.remove("material_name");for(const auto &v:m_asset["metadata"].toObject()["materials"].toArray()){const auto material=v.toObject();if(material["slot"].toInt()==m_slot->value()){o["material_name"]=material["name"];break;}}}item->setData(Qt::UserRole,o);item->setText(m_label->text().isEmpty()?o["target"].toObject()["name"].toString(o["target_id"].toString()):m_label->text());}}
void OrderedEditor::move(int direction){const int row=m_list->currentRow(),target=row+direction;if(row<0||target<0||target>=m_list->count())return;auto item=m_list->takeItem(row);m_list->insertItem(target,item);m_list->setCurrentItem(item);}
void OrderedEditor::addLibrary(){auto picker=new AssetPicker(m_rpc,m_thumbs,tr("选择关联资产"),m_mode==Previews?QStringList{"image","source"}:QStringList{},this);picker->setAttribute(Qt::WA_DeleteOnClose);connect(picker,&QDialog::accepted,this,[this,picker]{for(const auto &v:picker->selectedAssets()){const auto a=v.toObject();if(a["id"]==m_asset["id"])continue;addItem({{"target_id",a["id"]},{"target",a},{"label",a["name"]},{"role",""},{"slot",1},{"normal_y","opengl"}});}});picker->open();}
void OrderedEditor::save(){QJsonArray items;QSet<QString> roles;for(int i=0;i<m_list->count();++i){auto o=m_list->item(i)->data(Qt::UserRole).toJsonObject();const QString role=o["role"].toString();if(m_mode==Relations&&!role.isEmpty()){const auto key=role+":"+QString::number(o["slot"].toInt(1));if(roles.contains(key)){GlassMessages::information(this,tr("重复绑定"),tr("同一槽位的同一渲染角色只能绑定一张贴图。请调整角色或槽位。"));return;}roles.insert(key);}o.remove("target");items.append(o);}m_save->setEnabled(false);QJsonObject params{{"asset_id",m_asset["id"]},{"revision",m_asset["revision"]},{"items",items}};if(m_mode==Previews)params["cover_id"]=m_cover;m_rpc->call(m_mode==Relations?"relation.set":"preview.set",params,this,[this](const QJsonObject &r,const QString &err){m_save->setEnabled(true);if(!err.isEmpty()){GlassMessages::warning(this,tr("保存失败"),err);return;}emit saved(r);m_rpc->refresh();accept();});}
